  _ = `Τα μηνύματα μάρκετινγκ που προκύπτουν από μια μεγάλη ενημέρωση απαιτούν έλεγχο από τη Valve μέσω δελτίου, προκειμένου να διασφαλιστεί ότι πληρούν τα κριτήρια ποιότητας για ένα μήνυμα μάρκετινγκ. Αυτό το δελτίο δημιουργείται στην καρτέλα δημοσίευσης του συμβάντος ενημέρωσης.`,
