  _ = `Αυτό το συμβάν δεν είναι ακόμα ορατό, αλλά σας το δείχνουμε επειδή έχετε ένα παιχνίδι που είναι καταχωρισμένο στη σελίδα προσφοράς. Αν αυτό δεν είναι αναμενόμενο, επικοινωνήστε με τους διοργανωτές της προσφοράς.`,
