  _ = `Υπάρχει ένα παιχνίδι για το οποίο απαιτείται το δικαίωμα «%2$s» προκειμένου να δείτε λεπτομερή στατιστικά στοιχεία.`,
  _ = `Υπάρχουν %1$s παιχνίδια για τα οποία απαιτείται το δικαίωμα «%2$s» προκειμένου να δείτε λεπτομερή στατιστικά στοιχεία.`,
