  _ = `Προβολή τεκμηρίωσης`,
  _ = `Τα παιχνίδια απαιτούν χαρακτηρισμό καταλληλότητας για πώληση στη Γερμανία: 15 Νοεμβρίου`,
  _ = `Μία από τις εφαρμογές σας δεν έχει γερμανικό χαρακτηρισμό καταλληλότητας. Από τις 15 Νοεμβρίου 2024, το Steam δεν θα εμφανίζει πλέον αυτόν τον τίτλο σε πελάτες που χρησιμοποιούν το Κατάστημα Steam στη Γερμανία. Για να διασφαλίσετε ότι το παιχνίδι σας θα είναι διαθέσιμο προς πώληση στη Γερμανία, συμπληρώστε και δημοσιεύστε το ενσωματωμένο ερωτηματολόγιο περιεχομένου του Steam.`,
  _ = `Πολλές από τις εφαρμογές σας δεν έχουν γερμανικό χαρακτηρισμό καταλληλότητας. Από τις 15 Νοεμβρίου 2024, το Steam δεν θα εμφανίζει πλέον αυτούς τους τίτλους σε πελάτες που χρησιμοποιούν το Κατάστημα Steam στη Γερμανία. Για να διασφαλίσετε ότι τα παιχνίδια σας θα είναι διαθέσιμα προς πώληση στη Γερμανία, συμπληρώστε και δημοσιεύστε το ενσωματωμένο ερωτηματολόγιο περιεχομένου του Steam.`,
