  _ = `Προσθέστε τον εαυτό σας ή κάποιον συνάδελφο, για να είστε σίγουροι ότι θα λαμβάνετε σημαντικά email από το Steam.`,
  _ = `Αυτήν τη στιγμή, δεν έχει οριστεί κανένας χρήστης για να λαμβάνει επικοινωνία από το Steamworks. Χορηγήστε το δικαίωμα «Λήψη επικοινωνίας Steamworks» σε έναν ή περισσότερους χρήστες με έγκυρη διεύθυνση email, ώστε να μπορεί το Steam να ειδοποιεί κάποιον για επερχόμενες εκπτώσεις, συμβάντα, νέα χαρακτηριστικά ή άλλες ειδικές προσκλήσεις.`,
