  _ = `Η Valve θα ήθελε να σας στείλει κάτι. Αυτό είχε προθεσμία έως %1$s, αλλά μπορείτε ακόμα να μας δώσετε μια ταχυδρομική διεύθυνση ή να απορρίψετε το αίτημα.`,
  _ = `Η Valve θα ήθελε να σας στείλει κάτι. Δώστε μας μια ταχυδρομική διεύθυνση ή απορρίψτε το αίτημα.`,
