  _ = `Μη έγκυρο ID σετ: Το ID σετ δεν υπάρχει`,
  _ = `Αναταξινόμηση σετ`,
  _ = `Κάντε σύρσιμο και απόθεση σετ επιτευγμάτων για να επιλέξετε τη σειρά με την οποία θα εμφανίζονται στους χρήστες.`,
  _ = `Δεν είναι δυνατή η μετακίνηση του προεπιλεγμένου σετ`,
  _ = `Επιλογές`,
  _ = `Το πλάτος και το ύψος της εικόνας πρέπει να έχουν τις ίδιες διαστάσεις`,
  _ = `Οι διαστάσεις της εικόνας πρέπει να είναι τουλάχιστον %1$s x %1$s`,
  _ = `Άγνωστος τύπος περιεχομένου`,
  _ = `Δεν βρέθηκε επίτευγμα με το όνομα API «%1$s». Δεν ήταν δυνατή η αντιστοίχιση εικόνας.`,
  _ = `Το επίτευγμα «%1$s» λείπει από το μεταφορτωμένο αρχείο ορισμών CSV, οπότε δεν θα ανατεθεί αυτό το εικονίδιο. Προσθέστε το στο αρχείο CSV ή αφαιρέστε το αρχείο CSV για να μεταφορτώσετε τα εικονίδια από μόνα τους.`,
  _ = `Αυτό το επίτευγμα λείπει από το μεταφορτωμένο αρχείο ορισμών CSV, οπότε δεν θα ενημερωθεί η τοπική προσαρμογή του. Προσθέστε το στο αρχείο ορισμών CSV ή αφαιρέστε τα κείμενα τοπικής προσαρμογής του από αυτό το αρχείο.`,
  _ = `Δεν βρέθηκε κανένα επίτευγμα με αυτό το όνομα API, οπότε η τοπική προσαρμογή του δεν θα ενημερωθεί. Τα ονόματα API εδώ κάνουν διάκριση πεζών-κεφαλαίων.`,
  _ = `Έχετε μη αποθηκευμένες αλλαγές. Θέλετε σίγουρα να τις απορρίψετε;`,
  _ = `Μη έγκυρη μέγιστη τιμή προόδου: Η μέγιστη τιμή προόδου επιτευγμάτων πρέπει να είναι μικρότερη ή ίση με τη μέγιστη στατιστική τιμή`,
  _ = `Γλώσσες επιτευγμάτων`,
  _ = `Επιλέξτε τις γλώσσες τις οποίες υποστηρίζουν τα επιτεύγματά σας. Αυτό θα τις ενεργοποιήσει για τοπική προσαρμογή στο πρόγραμμα επεξεργασίας επιτευγμάτων και θα επιτρέψει τη μαζική εξαγωγή και εισαγωγή επιτευγμάτων. Όταν κάνετε ερωτήματα για επιτεύγματα μέσω του API, το Steam θα επιστρέφει το τοπικά προσαρμοσμένο κείμενο.`,
  _ = `Αποθήκευση εισαγόμενων δεδομένων`,
  _ = `ΝΕΟ`,
